import sys
from math import isqrt

def count_divisors_sum_to(n):
    count = 0
    for i in range(1, isqrt(n) + 1):
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
    return count

def find_x_for_J_equals_A(A):
    count = 0
    for x in range(1, A + 1):
        if sum(i for i in range(1, x + 1) if x % i == 0) == A:
            count += 1
    return count

def main():
    A = int(sys.stdin.read().strip())
    result = find_x_for_J_equals_A(A)
    print(result)

